 "content": "def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(set(v for row in g for v in row), key=lambda v: sum(r.count(v) for r in g))
    # Identify the two horizontal bars of the non-background color other than the marker.
    runs = []
    for r, row in enumerate(g):
        c = 0
        while c < w:
            if row[c] == bg:
                c += 1
                continue
            color = row[c]
            end = c + 1
            while end < w and row[end] == color:
                end += 1
            if end - c > 1:
                runs.append((r, c, end, color))
            c = end
    if len(runs) < 2:
        return g
    runs.sort(key=lambda x: x[0])
    top, bottom = runs[0], runs[-1]
    # Single isolated cell is the source point.
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    marker = next((v for v, n in counts.items() if v != bg and n == 1), None)
    if marker is None:
        return g
    mr = next(r for r in range(h) for c in range(w) if g[r][c] == marker)
    mc = next(c for c in range(w) if g[mr][c] == marker)
    def mapped_col(src, c):
        return min(src[2] - src[1] - 1, max(0, c - src[1]))
    # Continue a vertical signal from the source toward its bar and from the corresponding
    # position on each bar toward the opposite bar.
    for bar in (top, bottom):
        col = bar[1] + mapped_col(bar, mc)
        if bar[0] < mr:
            for r in range(bar[0] + 1, mr):
                g[r][col] = marker
        elif bar[0] > mr:
            for r in range(mr + 1, bar[0]):
                g[r][col] = marker
    g[mr][mc] = 4
    other = bottom if mr < bottom[0] else top
    col = other[1] + mapped_col(top if mr < bottom[0] else bottom, mc)
    # Vertical ray on the opposite bar continues along the full gap.
    for r in range(min(top[0], bottom[0]) + 1, max(top[0], bottom[0])):
        if g[r][col] == bg:
            g[r][col] = marker
    return g
